import json,sys
d=json.load(sys.stdin)
# Look for any element with employment data, like numbers in thousands
for i, elem in enumerate(d['document']['elements']):
    content = str(elem.get('content', ''))
    # Look for patterns like 146, 168 etc. (thousands) along with Q1, Q2
    if ('Q1' in content or 'Q2' in content or 'quarter' in content.lower()) and ('2004' in content or '2005' in content or '2006' in content):
        if len(content) > 100 and len(content) < 500:
            print(f'Element {i}: {content}')"
